import 'mapping_descriptor.dart';
import 'mapping_fingerprint.dart';

/// Checks a descriptor before it is used by a feed.
///
/// This is the deterministic guardrail for descriptors written by hand or
/// generated by a build-time LLM: it catches missing canonical fields, empty
/// paths, and contradictory pagination/envelope settings without calling a
/// model at runtime.
List<String> validateFeedMappingDescriptor(
  FeedMappingDescriptor descriptor, {
  required Set<String> requiredFields,
  bool requireProvenance = false,
  bool requireFingerprint = false,
}) {
  final issues = <String>[];

  if (descriptor.itemsPath.trim().isEmpty) {
    issues.add('itemsPath must not be empty');
  }
  if (descriptor.schemaVersion < 1) {
    issues.add('schemaVersion must be >= 1');
  }
  if (descriptor.fields.isEmpty) {
    issues.add('fields must not be empty');
  }

  final provenance = descriptor.provenance;
  if (provenance == null) {
    if (requireProvenance) {
      issues.add('provenance is required');
    }
  } else {
    _validateProvenance(provenance, issues);
    if (requireFingerprint) {
      if (provenance.fixtureHash == null || provenance.fixtureHash!.isEmpty) {
        issues.add('provenance.fixtureHash is required');
      }
      if (provenance.sourceSchemaHash == null ||
          provenance.sourceSchemaHash!.isEmpty) {
        issues.add('provenance.sourceSchemaHash is required');
      }
    }
  }

  for (final field in requiredFields) {
    if (!descriptor.fields.containsKey(field)) {
      issues.add('missing required field: $field');
    }
  }

  for (final entry in descriptor.fields.entries) {
    final mapping = entry.value;
    final hasPath = mapping.path?.trim().isNotEmpty ?? false;
    final hasTemplate = mapping.template?.trim().isNotEmpty ?? false;
    if (hasPath == hasTemplate) {
      issues.add('field ${entry.key} must set exactly one of path or template');
    }
    if (mapping.fallbackPath != null && mapping.fallbackPath!.trim().isEmpty) {
      issues.add('field ${entry.key} has an empty fallbackPath');
    }
    if (mapping.transform != null && mapping.transform!.trim().isEmpty) {
      issues.add('field ${entry.key} has an empty transform');
    }
    if (mapping.description != null && mapping.description!.trim().isEmpty) {
      issues.add('field ${entry.key} has an empty description');
    }
    if (mapping.examples.any((example) => example.trim().isEmpty)) {
      issues.add('field ${entry.key} has an empty example');
    }
  }

  final hasTotalCount = descriptor.totalCountPath != null;
  final hasPageSize = descriptor.pageSize != null;
  if (hasTotalCount != hasPageSize) {
    issues.add('totalCountPath and pageSize must be set together');
  }
  if (descriptor.pageSize != null && descriptor.pageSize! <= 0) {
    issues.add('pageSize must be positive');
  }
  final hasContinuation = descriptor.continuationTokenPath != null;
  if (hasContinuation && descriptor.continuationTokenPath!.trim().isEmpty) {
    issues.add('continuationTokenPath must not be empty');
  }
  if (hasContinuation && descriptor.hasMorePath != null) {
    issues.add('continuationTokenPath and hasMorePath are mutually exclusive');
  }
  if (hasContinuation && hasTotalCount) {
    issues.add(
      'continuationTokenPath and totalCountPath are mutually exclusive',
    );
  }
  if (descriptor.hasMorePath != null && hasTotalCount) {
    issues.add('hasMorePath and totalCountPath are mutually exclusive');
  }

  final hasSuccessCode = descriptor.successCode != null;
  final hasSuccessCodePath = descriptor.successCodePath != null;
  if (hasSuccessCode != hasSuccessCodePath) {
    issues.add('successCode and successCodePath must be set together');
  }

  return issues;
}

void _validateProvenance(MappingProvenance provenance, List<String> issues) {
  if (provenance.generatedBy.trim().isEmpty) {
    issues.add('provenance.generatedBy must not be empty');
  }
  if (provenance.promptVersion.trim().isEmpty) {
    issues.add('provenance.promptVersion must not be empty');
  }
  if (!RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(provenance.generatedAt)) {
    issues.add('provenance.generatedAt must be YYYY-MM-DD');
  }
  if (provenance.reviewer.trim().isEmpty) {
    issues.add('provenance.reviewer must not be empty');
  }
  for (final entry in {
    'fixtureHash': provenance.fixtureHash,
    'sourceSchemaHash': provenance.sourceSchemaHash,
  }.entries) {
    final value = entry.value;
    if (value != null && !RegExp(r'^[0-9a-f]{8}$').hasMatch(value)) {
      issues.add('provenance.${entry.key} must be 8 lowercase hex chars');
    }
  }
}
